using System;using System.Configuration;using System.Data;using System.Data.SqlClient;using System.Net;using System.Web.UI;using System.Web.UI.WebControls;using System.Xml;namespace ZavaAccountManager{public partial class Default:Page{private const string CustomerKey="SelectedCustomerId";protected void Page_Load(object sender,EventArgs e){if(!Request.IsAuthenticated){Response.Redirect("~/Login.aspx?ReturnUrl="+Server.UrlEncode(Request.RawUrl),false);Context.ApplicationInstance.CompleteRequest();return;}if(!IsPostBack){BindCustomers();BindAccountTypes();lblActionStatus.Text="Select a customer.";}}protected void gvCustomers_SelectedIndexChanged(object sender,EventArgs e){if(gvCustomers.SelectedDataKey==null)return;var customerId=Convert.ToInt32(gvCustomers.SelectedDataKey.Value);ViewState[CustomerKey]=customerId;lblSelectedCustomer.Text=" - Customer ID "+customerId;BindAccounts(customerId);}protected void gvAccounts_RowCommand(object sender,GridViewCommandEventArgs e){int i;if(!int.TryParse(Convert.ToString(e.CommandArgument),out i)||i<0||i>=gvAccounts.Rows.Count)return;var accountId=Convert.ToInt32(gvAccounts.DataKeys[i].Value);if(e.CommandName=="CloseAccount"){using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("UPDATE Accounts SET Status='Closed',CloseDate=GETDATE(),ModifiedDate=GETDATE() WHERE AccountID=@i",c)){cmd.Parameters.AddWithValue("@i",accountId);c.Open();cmd.ExecuteNonQuery();}RebindAccounts();lblActionStatus.Text="Account closed.";}else if(e.CommandName=="ShowBalance"){lblBalanceResult.Text=GetBalance(accountId);}else if(e.CommandName=="ShowTransactions"){BindTransactions(accountId);}}protected void fvOpenAccount_ItemInserting(object sender,FormViewInsertEventArgs e){var t1=(TextBox)fvOpenAccount.FindControl("txtNewCustomerId");var d=(DropDownList)fvOpenAccount.FindControl("ddlAccountType");var t2=(TextBox)fvOpenAccount.FindControl("txtOpeningBalance");int cid,atid;decimal bal;if(!int.TryParse(t1.Text,out cid)||!int.TryParse(d.SelectedValue,out atid)||!decimal.TryParse(t2.Text,out bal)){e.Cancel=true;lblActionStatus.Text="Invalid values.";return;}using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("INSERT INTO Accounts (CustomerID,AccountTypeID,AccountNumber,Balance,AvailableBalance,Status,OpenDate,LastActivityDate,CreatedDate,ModifiedDate) VALUES (@c,@t,@n,@b,@b,'Active',GETDATE(),GETDATE(),GETDATE(),GETDATE())",c)){cmd.Parameters.AddWithValue("@c",cid);cmd.Parameters.AddWithValue("@t",atid);cmd.Parameters.AddWithValue("@n",DateTime.UtcNow.ToString("yyMMddHHmmss")+cid.ToString("00"));cmd.Parameters.AddWithValue("@b",bal);c.Open();cmd.ExecuteNonQuery();}ViewState[CustomerKey]=cid;BindAccounts(cid);lblActionStatus.Text="Account opened.";e.Cancel=true;}private void BindCustomers(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT TOP 20 CustomerID, FirstName, LastName, Email, Status FROM Customers ORDER BY CustomerID;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}gvCustomers.DataSource=t;gvCustomers.DataBind();}private void BindAccounts(int customerId){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT AccountID, AccountNumber, Balance, AvailableBalance, Status, OpenDate FROM Accounts WHERE CustomerID=@c ORDER BY AccountID DESC;",c))using(var a=new SqlDataAdapter(cmd)){cmd.Parameters.AddWithValue("@c",customerId);c.Open();a.Fill(t);}gvAccounts.DataSource=t;gvAccounts.DataBind();}private void BindAccountTypes(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT AccountTypeID, TypeName FROM AccountTypes WHERE IsActive=1 ORDER BY TypeName;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}var ddl=(DropDownList)fvOpenAccount.FindControl("ddlAccountType");if(ddl!=null){ddl.DataSource=t;ddl.DataTextField="TypeName";ddl.DataValueField="AccountTypeID";ddl.DataBind();}}private string GetBalance(int accountId){try{var r=(HttpWebRequest)WebRequest.Create((ConfigurationManager.AppSettings["LedgerBaseUrl"]??"http://zava-ledger:8080").TrimEnd('/')+"/api/accounts/"+accountId+"/balance");using(var resp=(HttpWebResponse)r.GetResponse())using(var s=resp.GetResponseStream()){var x=new XmlDocument();x.Load(s);return "Balance: "+(x.SelectSingleNode("//balance")?.InnerText??"n/a")+" Available: "+(x.SelectSingleNode("//availableBalance")?.InnerText??"n/a");}}catch{return "Ledger balance unavailable.";}}private void BindTransactions(int accountId){var t=new DataTable();t.Columns.Add("TransactionID");t.Columns.Add("Amount");t.Columns.Add("Description");t.Columns.Add("ReferenceNumber");t.Columns.Add("TransactionDate");t.Columns.Add("Status");try{var r=(HttpWebRequest)WebRequest.Create((ConfigurationManager.AppSettings["LedgerBaseUrl"]??"http://zava-ledger:8080").TrimEnd('/')+"/api/accounts/"+accountId+"/transactions");using(var resp=(HttpWebResponse)r.GetResponse())using(var s=resp.GetResponseStream()){var x=new XmlDocument();x.Load(s);foreach(XmlNode n in x.SelectNodes("//transaction")){var row=t.NewRow();row["TransactionID"]=n.SelectSingleNode("transactionId")?.InnerText;row["Amount"]=n.SelectSingleNode("amount")?.InnerText;row["Description"]=n.SelectSingleNode("description")?.InnerText;row["ReferenceNumber"]=n.SelectSingleNode("referenceNumber")?.InnerText;row["TransactionDate"]=n.SelectSingleNode("transactionDate")?.InnerText;row["Status"]=n.SelectSingleNode("status")?.InnerText;t.Rows.Add(row);}}}catch{using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT TOP 25 TransactionID, Amount, Description, ReferenceNumber, TransactionDate, Status FROM Transactions WHERE AccountID=@a ORDER BY TransactionDate DESC;",c))using(var a=new SqlDataAdapter(cmd)){cmd.Parameters.AddWithValue("@a",accountId);c.Open();a.Fill(t);}}gvTransactionHistory.DataSource=t;gvTransactionHistory.DataBind();}private void RebindAccounts(){if(ViewState[CustomerKey]!=null)BindAccounts(Convert.ToInt32(ViewState[CustomerKey]));}}}
